CREATE TABLE IF NOT EXISTS base_foods (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) UNIQUE NOT NULL,
    category VARCHAR(100),
    calories FLOAT,
    protein FLOAT,
    carbs FLOAT,
    fat FLOAT,
    fiber FLOAT,
    sugar FLOAT,
    sodium FLOAT,
    chol FLOAT
);

-- Clear existing just in case
TRUNCATE TABLE base_foods RESTART IDENTITY;

